import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static int p, k;
    static long ans;
    static boolean[] vis;

    static long solve() {
        ans = 1;
        if (k == 0) {
            for (int i = 1; i < p; ++i) {
                ans = (ans * p) % MOD;
            }
        } else if (k == 1) {
            for (int i = 1; i <= p; ++i) {
                ans = (ans * p) % MOD;
            }
        } else {
            for (int i = 0; i < p; ++i) {
                if (!vis[i]) {
                    int len = 0;
                    int current = i;
                    while (!vis[current]) {
                        vis[current] = true;
                        ++len;
                        current = (int)((long)current * k % p);
                    }
                    if (current != 0) {
                        ans = (ans * p) % MOD;
                    }
                }
            }
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p = sc.nextInt();
        k = sc.nextInt();
        vis = new boolean[p];
        System.out.println(solve());
        sc.close();
    }
}
